@Override
  public void doPaint(Graphics2D g) {

    // X-Axis
    double xTickSpace = stylerCategory.getPlotContentSize() * getBounds().getWidth();
    double xLeftMargin = Utils.getTickStartOffset(getBounds().getWidth(), xTickSpace);
    Map<String, S> seriesMap = chart.getSeriesMap();
    int numCategories = seriesMap.values().iterator().next().getXData().size();
    double gridStep = xTickSpace / numCategories;

    // Y-Axis
    double yMin = axesChart.getYAxis().getMin();
    double yMax = axesChart.getYAxis().getMax();

    // figure out the general form of the chart
    final int chartForm; // 1=positive, -1=negative, 0=span
    if (yMin > 0.0 && yMax > 0.0) {
      chartForm = 1; // positive chart
    } else if (yMin < 0.0 && yMax < 0.0) {
      chartForm = -1; // negative chart
    } else {
      chartForm = 0; // span chart
    }

    double yTickSpace = stylerCategory.getPlotContentSize() * getBounds().getHeight();
    double yTopMargin = Utils.getTickStartOffset(getBounds().getHeight(), yTickSpace);

    // plot series
    int seriesCounter = 0;
    double[] accumulatedStackOffsetPos = new double[numCategories];
    double[] accumulatedStackOffsetNeg = new double[numCategories];
    double[] accumulatedStackOffsetTotalYOffset = new double[numCategories];

    // For stacked area charts, each series is drawn as a filled band between the previous series'
    // cumulative line (the floor) and its own cumulative line. Positive and negative stacks grow
    // away from the value-zero line in opposite directions (mirroring stacked bars), so track a
    // floor per direction per category, both starting at the zero line.
    double yAxisMinChart = axesChart.getYAxis().getMin();
    double yAxisMaxChart = axesChart.getYAxis().getMax();
    double zeroValue = Math.max(yAxisMinChart, Math.min(yAxisMaxChart, 0.0));
    double zeroLineYOffset =
        getBounds().getY()
            + getBounds().getHeight()
            - (yTopMargin
                + (zeroValue - yAxisMinChart) / (yAxisMaxChart - yAxisMinChart) * yTickSpace);
    double[] stackedAreaFloorYOffsetPos = new double[numCategories];
    double[] stackedAreaFloorYOffsetNeg = new double[numCategories];
    Arrays.fill(stackedAreaFloorYOffsetPos, zeroLineYOffset);
    Arrays.fill(stackedAreaFloorYOffsetNeg, zeroLineYOffset);

    for (S series : seriesMap.values()) {

      if (!series.isEnabled()) {
        continue;
      }

      yMin = axesChart.getYAxis(series.getYAxisGroup()).getMin();
      yMax = axesChart.getYAxis(series.getYAxisGroup()).getMax();
      if (stylerCategory.isYAxisLogarithmic()) {
        yMin = Math.log10(yMin);
        yMax = Math.log10(yMax);
      }

      // for line series
      double previousX = -Double.MAX_VALUE;
      double previousY = -Double.MAX_VALUE;

      // smooth curve path for Line render style
      Path2D.Double smoothPath = null;

      List<?> xDataList = (List<?>) series.getXData();
      double[] yArr = series.getYData();
      double[] errorBars = series.getExtraValues();

      // Line and Scatter series are drawn at their own values; they never participate in stacking.
      boolean seriesStacked =
          stylerCategory.isStacked()
              && series.getChartCategorySeriesRenderStyle().orElseThrow().isStackable();

      // Stepped bars are drawn in chunks rather than for each individual bar
      ArrayList<Point2D.Double> steppedPath = new ArrayList<>();
      ArrayList<Point2D.Double> steppedReturnPath = new ArrayList<>();
      // Stacked area top points and matching floor Y-offsets, collected across the data loop and
      // painted as a single filled band afterward.
      ArrayList<Point2D.Double> stackedAreaTopPoints = new ArrayList<>();
      ArrayList<Double> stackedAreaFloorYOffsets = new ArrayList<>();
      Path2D.Double path = null;
      int categoryCounter = 0;

      for (int dataIndex = 0; dataIndex < yArr.length; dataIndex++) {

        double next = yArr[dataIndex];
        // skip when a value is NaN (was null in the original list)
        if (Double.isNaN(next)) {

          if (smoothPath != null) {
            g.setColor(series.getLineColor());
            g.setStroke(series.getLineStyle());
            g.draw(smoothPath);
            smoothPath = null;
          }

          // flush the current stacked-area band so it does not bridge across the gap
          fillStackedAreaBand(
              g, series, stackedAreaTopPoints, stackedAreaFloorYOffsets, series.isSmooth());

          previousX = -Double.MAX_VALUE;
          previousY = -Double.MAX_VALUE;
          categoryCounter++;
          continue;
        }
        Object nextCat = xDataList.get(dataIndex);

        double yOrig = next;
        double y;
        if (stylerCategory.isYAxisLogarithmic()) {
          y = Math.log10(yOrig);
        } else {
          y = yOrig;
        }

        double yTop = 0.0;
        double yBottom = 0.0;
        switch (chartForm) {
          case 1: // positive chart
            // check for points off the chart draw area due to a custom yMin
            if (y < yMin) {
              categoryCounter++;
              continue;
            }
            yTop = y;
            yBottom = yMin;
            if (seriesStacked) {
              yTop += accumulatedStackOffsetPos[categoryCounter];
              yBottom += accumulatedStackOffsetPos[categoryCounter];
              accumulatedStackOffsetPos[categoryCounter] += (yTop - yBottom);
            }
            break;
          case -1: // negative chart
            // check for points off the chart draw area due to a custom yMin
            if (y > yMax) {
              categoryCounter++;
              continue;
            }
            yTop = yMax;
            yBottom = y;
            if (seriesStacked) {
              yTop -= accumulatedStackOffsetNeg[categoryCounter];
              yBottom -= accumulatedStackOffsetNeg[categoryCounter];
              accumulatedStackOffsetNeg[categoryCounter] += (yTop - yBottom);
            }
            break;
          case 0: // span chart
            if (y >= 0.0) { // positive
              yTop = y;
              if (series.getChartCategorySeriesRenderStyle().orElseThrow()
                      == CategorySeriesRenderStyle.Bar
                  || series.getChartCategorySeriesRenderStyle().orElseThrow()
                      == CategorySeriesRenderStyle.Stick
                  || series.getChartCategorySeriesRenderStyle().orElseThrow()
                      == CategorySeriesRenderStyle.SteppedBar) {
                yBottom = 0.0;
              } else {
                yBottom = y;
              }
              if (seriesStacked && !series.isOverlapped()) {
                yTop += accumulatedStackOffsetPos[categoryCounter];
                yBottom += accumulatedStackOffsetPos[categoryCounter];
                // Grow the stack by the actual value. For bars (yBottom == 0) this equals
                // (yTop - yBottom), but for area/line (yBottom == yTop) that difference would be 0,
                // so the stack must be advanced by y directly.
                accumulatedStackOffsetPos[categoryCounter] += y;
              }
            } else {
              if (series.getChartCategorySeriesRenderStyle().orElseThrow()
                      == CategorySeriesRenderStyle.Bar
                  || series.getChartCategorySeriesRenderStyle().orElseThrow()
                      == CategorySeriesRenderStyle.Stick
                  || series.getChartCategorySeriesRenderStyle().orElseThrow()
                      == CategorySeriesRenderStyle.SteppedBar) {
                yTop = 0.0;
              } else {
                yTop = y; // yTransform uses yTop, and for non-bars and stick, it's the same as
                // yBottom.
              }
              yBottom = y;
              if (seriesStacked && !series.isOverlapped()) {
                yTop -= accumulatedStackOffsetNeg[categoryCounter];
                yBottom -= accumulatedStackOffsetNeg[categoryCounter];
                // Grow the negative stack by the magnitude of y (y < 0 here), for the same reason
                // as the positive branch: for area/line (yTop - yBottom) would be 0.
                accumulatedStackOffsetNeg[categoryCounter] -= y;
              }
            }
            break;
          default:
            break;
        }

        double yTransform =
            getBounds().getHeight() - (yTopMargin + (yTop - yMin) / (yMax - yMin) * yTickSpace);
        double yOffset = getBounds().getY() + yTransform;

        // Record the first series yOffset value, update totalYOffset value
        // when next is greater then 0
        if (seriesCounter == 0 || next > 0) {
          accumulatedStackOffsetTotalYOffset[categoryCounter] = yOffset;
        }

        double zeroTransform =
            getBounds().getHeight() - (yTopMargin + (yBottom - yMin) / (yMax - yMin) * yTickSpace);
        double zeroOffset = getBounds().getY() + zeroTransform;

        // compute bar width and x position
        double[] dims =
            computeBarDimensions(series, categoryCounter, gridStep, xLeftMargin, seriesCounter);
        double barWidth = dims[0];
        double xOffset = dims[1];
        categoryCounter++;

        // render by style
        if (series.getChartCategorySeriesRenderStyle().orElseThrow()
            == CategorySeriesRenderStyle.SteppedBar) {

          previousY =
              processSteppedBarDataPoint(
                  g,
                  series,
                  y,
                  yOffset,
                  zeroOffset,
                  xOffset,
                  gridStep,
                  seriesCounter,
                  dataIndex == yArr.length - 1,
                  steppedPath,
                  steppedReturnPath,
                  previousY);

        } else if (series.getChartCategorySeriesRenderStyle().orElseThrow()
            == CategorySeriesRenderStyle.Bar) {

          // paint bar
          Path2D.Double barPath = new Path2D.Double();
          barPath.moveTo(xOffset, yOffset);
          barPath.lineTo(xOffset + barWidth, yOffset);
          barPath.lineTo(xOffset + barWidth, zeroOffset);
          barPath.lineTo(xOffset, zeroOffset);
          barPath.closePath();

          g.setColor(series.getFillColor());
          g.fill(barPath);

          // TODO maybe we want outlines of the bars?
          // Legend markers now also draw the outline. It has been disabled for
          // CategorySeriesRenderStyle.Bar
          // in Legend_Marker.java. Modify accordingly if you are enabling bar outlines.
          // if (series.getLineColor() != null) {
          // path = new Path2D.Double();
          // int halfLineWidth = (int) (series.getLineStyle().getLineWidth() / 2 + .1);
          // path.moveTo(xOffset + halfLineWidth, yOffset + halfLineWidth);
          // path.lineTo(xOffset + halfLineWidth + barWidth - halfLineWidth * 2, yOffset +
          // halfLineWidth);
          // path.lineTo(xOffset + halfLineWidth + barWidth - halfLineWidth * 2, zeroOffset -
          // halfLineWidth);
          // path.lineTo(xOffset + halfLineWidth, zeroOffset - halfLineWidth);
          // path.closePath();
          //
          // g.setStroke(series.getLineStyle());
          // g.setColor(series.getLineColor());
          // g.draw(path);
          // }

          if (stylerCategory.isLabelsVisible()) {
            drawLabels(
                g,
                next,
                xOffset,
                yOffset,
                zeroOffset,
                barWidth,
                false,
                false,
                series.getFillColor());
          }
          if (stylerCategory.isLabelsVisible()
              && stylerCategory.isShowStackSum()
              && stylerCategory.isStacked()
              && seriesCounter == (seriesMap.size() - 1)) {
            double totalNext =
                accumulatedStackOffsetPos[categoryCounter - 1]
                    - accumulatedStackOffsetNeg[categoryCounter - 1];
            double totalYOffset = accumulatedStackOffsetTotalYOffset[categoryCounter - 1];
            drawLabels(
                g,
                totalNext,
                xOffset,
                totalYOffset,
                zeroOffset,
                barWidth,
                true,
                true,
                series.getFillColor());
          }
        } else if (CategorySeriesRenderStyle.Stick.equals(
            series.getChartCategorySeriesRenderStyle().orElseThrow())) {

          // paint stick
          if (series.getLineStyle() != SeriesLines.NONE) {

            g.setColor(series.getLineColor());
            g.setStroke(series.getLineStyle());
            Shape line =
                new Line2D.Double(
                    xOffset + barWidth / 2, zeroOffset, xOffset + barWidth / 2, yOffset);
            g.draw(line);
          }

          // paint marker
          if (series.getMarker() != null) {
            g.setColor(series.getMarkerColor());

            if (y <= 0) {
              series
                  .getMarker()
                  .paint(g, xOffset + barWidth / 2, zeroOffset, stylerCategory.getMarkerSize());
            } else {
              series
                  .getMarker()
                  .paint(g, xOffset + barWidth / 2, yOffset, stylerCategory.getMarkerSize());
            }
          }
        } else {

          // paint line
          if (series.getChartCategorySeriesRenderStyle().orElseThrow()
              == CategorySeriesRenderStyle.Line) {

            if (series.getLineStyle() != SeriesLines.NONE) {

              if (previousX != -Double.MAX_VALUE && previousY != -Double.MAX_VALUE) {
                g.setColor(series.getLineColor());
                g.setStroke(series.getLineStyle());
                if (series.isSmooth()) {
                  if (smoothPath == null) {
                    smoothPath = new Path2D.Double();
                    smoothPath.moveTo(previousX, previousY);
                  }
                  smoothPath.curveTo(
                      (previousX + xOffset + barWidth / 2) / 2,
                      previousY,
                      (previousX + xOffset + barWidth / 2) / 2,
                      yOffset,
                      xOffset + barWidth / 2,
                      yOffset);
                } else {
                  Shape line =
                      new Line2D.Double(previousX, previousY, xOffset + barWidth / 2, yOffset);
                  g.draw(line);
                }
              }
            }
          }

          // paint area
          if (CategorySeriesRenderStyle.Area.equals(
              series.getChartCategorySeriesRenderStyle().orElseThrow())) {

            double xCenter = xOffset + barWidth / 2;

            if (seriesStacked && !series.isOverlapped()) {
              // Stacked: collect this point and the floor it rests on (the previous series'
              // cumulative line for this category). The band is filled after the data loop. Advance
              // the floor so the next series stacks on top of this series.
              double[] floors =
                  (y >= 0.0) ? stackedAreaFloorYOffsetPos : stackedAreaFloorYOffsetNeg;
              double floor = dataIndex < floors.length ? floors[dataIndex] : zeroLineYOffset;
              stackedAreaTopPoints.add(new Point2D.Double(xCenter, yOffset));
              stackedAreaFloorYOffsets.add(floor);
              if (dataIndex < floors.length) {
                floors[dataIndex] = yOffset;
              }
            } else if (previousX != -Double.MAX_VALUE && previousY != -Double.MAX_VALUE) {

              g.setColor(series.getFillColor());
              double yBottomOfArea = getBounds().getY() + getBounds().getHeight() - yTopMargin;

              if (path == null) {
                path = new Path2D.Double();
                path.moveTo(previousX, yBottomOfArea);
                path.lineTo(previousX, previousY);
              }
              if (series.isSmooth()) {
                path.curveTo(
                    (previousX + xCenter) / 2,
                    previousY,
                    (previousX + xCenter) / 2,
                    yOffset,
                    xCenter,
                    yOffset);
              } else {
                path.lineTo(xCenter, yOffset);
              }
            }
            if (xOffset < previousX) {
              throw new RuntimeException("X-Data must be in ascending order for Area Charts!!!");
            }
          }

          previousX = xOffset + barWidth / 2;
          previousY = yOffset;

          // paint marker
          if (series.getMarker() != null) {
            g.setColor(series.getMarkerColor());
            series.getMarker().paint(g, previousX, previousY, stylerCategory.getMarkerSize());
          }
        }

        // paint error bars
        if (errorBars != null) {

          double eb = errorBars[dataIndex];

          // set error bar style
          if (stylerCategory.isErrorBarsColorSeriesColor()) {
            g.setColor(series.getLineColor());
          } else {
            g.setColor(stylerCategory.getErrorBarsColor());
          }
          g.setStroke(ERROR_BAR_STROKE);

          // Top value
          if (stylerCategory.isYAxisLogarithmic()) {
            eb = Math.log10(eb);
          }
          double errorBarLength = ((eb) / (yMax - yMin) * yTickSpace);
          double topEBOffset;
          if (y > 0) {
            topEBOffset = yOffset - errorBarLength;
          } else {
            topEBOffset = zeroOffset - errorBarLength;
          }

          // Bottom value
          double bottomEBOffset;
          if (y > 0) {
            bottomEBOffset = yOffset + errorBarLength;
          } else {
            bottomEBOffset = zeroOffset + errorBarLength;
          }

          // Draw it
          double errorBarOffset = xOffset + barWidth / 2;
          Shape line =
              new Line2D.Double(errorBarOffset, topEBOffset, errorBarOffset, bottomEBOffset);
          g.draw(line);
          line =
              new Line2D.Double(
                  errorBarOffset - 3, bottomEBOffset, errorBarOffset + 3, bottomEBOffset);
          g.draw(line);
          line =
              new Line2D.Double(errorBarOffset - 3, topEBOffset, errorBarOffset + 3, topEBOffset);
          g.draw(line);
        }
        // add data labels
        if (interactionData != null) {
          Rectangle2D.Double rect =
              new Rectangle2D.Double(xOffset, yOffset, barWidth, Math.abs(yOffset - zeroOffset));
          double yPoint;
          if (y < 0) {
            yPoint = zeroOffset + 4 + 20 + 5;
          } else {
            yPoint = yOffset;
          }

          interactionData
              .addToolTip(
                  rect,
                  xOffset,
                  yPoint,
                  barWidth,
                  axesChart.getXAxisFormat().format(nextCat),
                  axesChart.getYAxisFormat().format(yOrig))
              .withSeries(series, dataIndex);
        }
      }

      // flush smooth path for line series
      if (smoothPath != null) {
        g.setColor(series.getLineColor());
        g.setStroke(series.getLineStyle());
        g.draw(smoothPath);
        smoothPath = null;
      }

      // close any open path for area charts
      g.setColor(series.getFillColor());
      closePath(g, path, previousX, getBounds(), yTopMargin);

      // fill any remaining stacked-area band (a series with no NaN gaps has one band)
      fillStackedAreaBand(
          g, series, stackedAreaTopPoints, stackedAreaFloorYOffsets, series.isSmooth());

      // Final drawing of a steppedBar is done after the main loop,
      // as it continues on null and we may end up missing the final iteration.
      finalizeSteppedBar(g, series, steppedPath, steppedReturnPath);

      seriesCounter++;
    }
  }

